function PVPArenaMatchResultDialog:ShowUI()
    self.isPlay = true
    cs_coroutine.start(function()
        local data       = self.data
        while self.count > 0 do
            local count      = self.count
            local resultData = data[count]
            local isShowResult, rank = resultData.isShowResult, resultData.rank
            self:RefreshUI(isShowResult, rank)

            if isShowResult then
                --KTool.SetActive(self.Group2.gameObject, true)
                --KTool.SetActive(self.Group1.gameObject, false)
                cs_coroutine.yield_return(self.Group1:WaitUntilAniCompleted())
            else
                --KTool.SetActive(self.Group1.gameObject, true)
                --KTool.SetActive(self.Group2.gameObject, false)
                cs_coroutine.yield_return(self.Group2:WaitUntilAniCompleted())
            end

            self.count = self.count - 1
            table.remove(data)
            if self.count > 0 then
                KTool.SetActive(self.Group1.gameObject, false)
                KTool.SetActive(self.Group2.gameObject, false)
                cs_coroutine.yield_return(WaitForSeconds)
            end
        end
        self.isPlay = false
    end)


end

function PVPArenaMatchResultDialog:RefreshUI(isShowResult, rank)
    KTool.SetActive(self.Group1.gameObject, isShowResult)
    KTool.SetActive(self.Group2.gameObject, not isShowResult)

    rank = checkInt(rank)
    if isShowResult then
        PVPArenaUtils.RefreshPVPRankFlagNode(self.PVPRankFlagNode.gameObject, rank)
        if rank > 4 then
            self.LoserTxtNumber.text = localize("_num_强", {_num_ = rank})
        end
    else
        KTool.SetActive(self.WinTxtNumberTip.gameObject, rank > 4)
        self.WinTxtNumber.text = PVPArenaUtils.GetRankTitleByRank(rank) or rank
    end
end

