function PVPArenaMatchResultDialog:OnEventUpdateMatchResultAction(data)
    if self.data == nil then return end
    for i, v in ipairs(data) do
        table.insert(self.data, 1, v)
        self.count = self.count + 1
    end
end

function PVPArenaMatchResultDialog:OnClickCloseLayerAction()
    UIModule.CloseDialog(self.controller)
end
